/** Fase 3: edición nativa básica con validación y escritura de vuelta a los datos activos. */
public class NativeHomeActivity extends Activity {
    private final int navy=Color.rgb(35,66,91), earth=Color.rgb(186,145,98), background=Color.rgb(247,248,250);
    private LinearLayout content; private String currentTab="Inicio"; private JSONObject data;
    private JSONArray products, sales, expenses, cashMovements, customers, creditMovements; private final LinkedHashMap<String,Integer> cart=new LinkedHashMap<>();
    @Override public void onCreate(Bundle state){super.onCreate(state); loadData(); showScreen("Inicio");}
    private void loadData(){data=NativeDataStore.readLegacyData(this); if(data==null)data=new JSONObject(); products=data.optJSONArray("products"); sales=data.optJSONArray("sales"); expenses=data.optJSONArray("expenses"); if(products==null){products=new JSONArray();try{data.put("products",products);}catch(Exception ignored){}} if(sales==null)sales=new JSONArray();if(expenses==null){expenses=new JSONArray();try{data.put("expenses",expenses);}catch(Exception ignored){}} cashMovements=data.optJSONArray("cashMovements");if(cashMovements==null){cashMovements=new JSONArray();try{data.put("cashMovements",cashMovements);}catch(Exception ignored){}} customers=data.optJSONArray("customers");if(customers==null){customers=new JSONArray();try{data.put("customers",customers);}catch(Exception ignored){}} creditMovements=data.optJSONArray("creditMovements");if(creditMovements==null){creditMovements=new JSONArray();try{data.put("creditMovements",creditMovements);}catch(Exception ignored){}}}
    private int dp(int v){return (int)(v*getResources().getDisplayMetrics().density+0.5f);}
    private TextView text(String v,int size,boolean bold,int color){TextView t=new TextView(this);t.setText(v);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);t.setPadding(dp(4),dp(5),dp(4),dp(5));return t;}
    private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(16),dp(12),dp(16),dp(12));return l;}
    private Button button(String label,int color){Button b=new Button(this);b.setText(label);b.setTextColor(Color.WHITE);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(color));return b;}
    private String money(double n){String c=data.optJSONObject("settings")!=null?data.optJSONObject("settings").optString("currency","MXN"):"MXN";try{return NumberFormat.getCurrencyInstance(new Locale("es","MX")).format(n)+" "+c;}catch(Exception e){return String.format(Locale.getDefault(),"%.2f %s",n,c);}}
    private double sum(JSONArray arr,String a,String b){double total=0;for(int i=0;i<arr.length();i++){JSONObject o=arr.optJSONObject(i);if(o!=null)total+=o.optDouble(a,o.optDouble(b,0));}return total;}
    private int lowStock(){int n=0;for(int i=0;i<products.length();i++){JSONObject p=products.optJSONObject(i);if(p!=null&&p.optDouble("stock",0)<=p.optDouble("minStock",0))n++;}return n;}
    private void showScreen(String tab){currentTab=tab;LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(background);LinearLayout header=new LinearLayout(this);header.setOrientation(LinearLayout.VERTICAL);header.setPadding(dp(20),dp(16),dp(20),dp(16));header.setBackgroundColor(navy);header.addView(text("Mi Primer Negocio 36",22,true,Color.WHITE));header.addView(text("Interfaz nativa · Fase 6",13,false,Color.rgb(225,232,238)));root.addView(header);ScrollView scroll=new ScrollView(this);content=column();scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=new LinearLayout(this);nav.setPadding(dp(5),dp(5),dp(5),dp(5));nav.setBackgroundColor(Color.WHITE);for(String item:new String[]{"Inicio","Inventario","Ventas","Operaciones","Clientes"}){Button b=new Button(this);b.setText(item);b.setTextSize(12);b.setTextColor(item.equals(tab)?navy:Color.DKGRAY);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(item.equals(tab)?0xFFE3EAF0:Color.WHITE));b.setOnClickListener(v->showScreen(item));nav.addView(b,new LinearLayout.LayoutParams(0,dp(50),1));}Button back=new Button(this);back.setText("Volver");back.setTextSize(12);back.setOnClickListener(v->finish());nav.addView(back,new LinearLayout.LayoutParams(0,dp(50),1));root.addView(nav);setContentView(root);if("Inicio".equals(tab))showHome();else if("Inventario".equals(tab))showInventory();else if("Ventas".equals(tab))showSales();else if("Clientes".equals(tab))showCustomers();else showOperations();}
    private void metric(String label,String value){LinearLayout card=column();card.setBackgroundColor(Color.WHITE);card.addView(text(label,13,false,Color.DKGRAY));card.addView(text(value,21,true,navy));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(10);content.addView(card,lp);}
    private void showHome(){content.addView(text("Resumen del negocio",24,true,navy));if(!data.has("products")){content.addView(text("No se encontró la copia de datos. Abre primero la pantalla principal y vuelve a intentarlo.",15,false,Color.RED));return;}metric("Productos registrados",String.valueOf(products.length()));metric("Productos con stock bajo",String.valueOf(lowStock()));metric("Ventas registradas",String.valueOf(sales.length()));metric("Gastos registrados",String.valueOf(expenses.length()));metric("Importe de ventas guardadas",money(sum(sales,"saleTotal","lineTotal")));content.addView(text("Los cambios de productos se guardan en los datos de la aplicación y se reflejan al regresar.",14,false,Color.DKGRAY));Button go=button("Administrar inventario",earth);go.setOnClickListener(v->showScreen("Inventario"));content.addView(go);}
    private void showInventory(){content.addView(text("Inventario",24,true,navy));content.addView(text("Agrega y edita productos desde esta pantalla",14,false,Color.DKGRAY));Button add=button("+ Agregar producto",navy);add.setOnClickListener(v->editProduct(-1));content.addView(add);if(products.length()==0){content.addView(text("Todavía no hay productos registrados.",15,false,Color.GRAY));return;}for(int i=0;i<products.length();i++){final int index=i;JSONObject p=products.optJSONObject(i);if(p==null)continue;LinearLayout card=column();card.setBackgroundColor(Color.WHITE);card.addView(text(p.optString("name",p.optString("nombre","Producto")),18,true,navy));card.addView(text("Existencias: "+p.optDouble("stock",0),15,false,Color.DKGRAY));card.addView(text("Precio: "+money(p.optDouble("price",0)),15,false,Color.DKGRAY));card.addView(text("Stock mínimo: "+p.optDouble("minStock",0),13,false,Color.GRAY));if(p.optDouble("stock",0)<=p.optDouble("minStock",0))card.addView(text("⚠ Stock bajo",13,true,Color.rgb(160,65,65)));Button edit=button("Editar producto",earth);edit.setOnClickListener(v->editProduct(index));card.addView(edit);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(10);content.addView(card,lp);}}
    private String productId(JSONObject p,int index){return p.optString("id", "native-product-"+index);}
    private JSONObject findProduct(String id){for(int i=0;i<products.length();i++){JSONObject p=products.optJSONObject(i);if(p!=null&&productId(p,i).equals(id))return p;}return null;}
    private double cartSubtotal(){double n=0;for(Map.Entry<String,Integer> e:cart.entrySet()){JSONObject p=findProduct(e.getKey());if(p!=null)n+=p.optDouble("price",0)*e.getValue();}return n;}
    private double taxRate(){JSONObject settings=data.optJSONObject("settings");return Math.max(0,Math.min(100,settings==null?0:settings.optDouble("taxRate",16)));}
    private String taxMode(){JSONObject settings=data.optJSONObject("settings");return settings==null?"add":settings.optString("taxMode","add");}
    private double taxAmount(double subtotal){if("off".equals(taxMode()))return 0;if("included".equals(taxMode()))return subtotal-subtotal/(1+taxRate()/100);return subtotal*taxRate()/100;}
    private double totalAmount(double subtotal){return "included".equals(taxMode())?subtotal:subtotal+taxAmount(subtotal);}
    private void showSales(){content.addView(text("Punto de venta",24,true,navy));content.addView(text("Agrega productos al carrito. Cada producto se registra dentro de un mismo folio de venta.",14,false,Color.DKGRAY));Button add=button("+ Agregar producto",navy);add.setOnClickListener(v->chooseProduct());content.addView(add);content.addView(text("Carrito",19,true,navy));if(cart.isEmpty())content.addView(text("El carrito está vacío.",15,false,Color.GRAY));
        for(Map.Entry<String,Integer> e:new LinkedHashMap<>(cart).entrySet()){JSONObject p=findProduct(e.getKey());if(p==null)continue;LinearLayout card=column();card.setBackgroundColor(Color.WHITE);card.addView(text(p.optString("name",p.optString("nombre","Producto")),17,true,navy));card.addView(text("Precio: "+money(p.optDouble("price",0))+" · Stock: "+p.optDouble("stock",0),13,false,Color.DKGRAY));LinearLayout controls=new LinearLayout(this);Button minus=button("−",earth),qty=button(String.valueOf(e.getValue()),navy),plus=button("+",earth),remove=button("Quitar",Color.rgb(160,65,65));minus.setOnClickListener(v->{int q=e.getValue()-1;if(q<=0)cart.remove(e.getKey());else cart.put(e.getKey(),q);showScreen("Ventas");});plus.setOnClickListener(v->{if(e.getValue()+1>p.optDouble("stock",0)){Toast.makeText(this,"No hay suficiente stock.",Toast.LENGTH_SHORT).show();return;}cart.put(e.getKey(),e.getValue()+1);showScreen("Ventas");});remove.setOnClickListener(v->{cart.remove(e.getKey());showScreen("Ventas");});controls.addView(minus,new LinearLayout.LayoutParams(0,dp(48),1));controls.addView(qty,new LinearLayout.LayoutParams(0,dp(48),1));controls.addView(plus,new LinearLayout.LayoutParams(0,dp(48),1));controls.addView(remove,new LinearLayout.LayoutParams(0,dp(48),1));card.addView(controls);card.addView(text("Importe: "+money(p.optDouble("price",0)*e.getValue()),15,true,navy));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(8);content.addView(card,lp);}
        double subtotal=cartSubtotal(),tax=taxAmount(subtotal),total=totalAmount(subtotal);metric("Subtotal",money(subtotal));if(!"off".equals(taxMode()))metric("Impuesto estimado",money(tax));metric("Total a cobrar",money(total));Button checkout=button("Cobrar y registrar venta",earth);checkout.setEnabled(!cart.isEmpty());checkout.setOnClickListener(v->checkout(total,subtotal,tax));content.addView(checkout);Button clear=button("Vaciar carrito",Color.DKGRAY);clear.setOnClickListener(v->{cart.clear();showScreen("Ventas");});content.addView(clear);content.addView(text("Ventas recientes",19,true,navy));java.util.LinkedHashMap<String,Double> recent=new java.util.LinkedHashMap<>();for(int i=sales.length()-1;i>=0&&recent.size()<10;i--){JSONObject sale=sales.optJSONObject(i);if(sale!=null){String id=sale.optString("saleId",sale.optString("id","Venta"));if(!recent.containsKey(id))recent.put(id,sale.optDouble("saleTotal",sale.optDouble("lineTotal",sale.optDouble("qty",0)*sale.optDouble("price",0))));}}for(Map.Entry<String,Double> e:recent.entrySet())content.addView(text("Folio "+e.getKey().substring(0,Math.min(10,e.getKey().length()))+" · "+money(e.getValue()),14,false,Color.DKGRAY));}
    private void saveAndSync(String success){
        try{data.put("products",products);data.put("sales",sales);data.put("expenses",expenses);data.put("cashMovements",cashMovements);
            if(!NativeDataStore.writeLegacyData(this,data)){Toast.makeText(this,"No se pudieron guardar los cambios.",Toast.LENGTH_LONG).show();return;}
            if(!MainActivity.applyNativeData(data.toString()))Toast.makeText(this,"Se guardó la copia nativa, pero no se confirmó la sincronización. Verifica la pantalla principal.",Toast.LENGTH_LONG).show();
            else Toast.makeText(this,success,Toast.LENGTH_SHORT).show();
            loadData();showScreen("Operaciones");
        }catch(Exception e){Toast.makeText(this,"Error al guardar: "+e.getMessage(),Toast.LENGTH_LONG).show();}
    }
    private String today(){return new SimpleDateFormat("yyyy-MM-dd",Locale.getDefault()).format(new Date());}
    private void showOperations(){
        content.addView(text("Gastos y operaciones",24,true,navy));
        content.addView(text("Registra gastos, ingresos y retiros. Los cambios se sincronizan con los datos del negocio.",14,false,Color.DKGRAY));
        double expenseTotal=0;for(int i=0;i<expenses.length();i++){JSONObject e=expenses.optJSONObject(i);if(e!=null)expenseTotal+=e.optDouble("amount",0);}
        double cashIn=0,cashOut=0;for(int i=0;i<cashMovements.length();i++){JSONObject m=cashMovements.optJSONObject(i);if(m!=null){if("income".equals(m.optString("kind")))cashIn+=m.optDouble("amount",0);else cashOut+=m.optDouble("amount",0);}}
        double cashSales=0;for(int i=0;i<sales.length();i++){JSONObject sale=sales.optJSONObject(i);if(sale!=null&&("cash".equals(sale.optString("payment"))||"efectivo".equals(sale.optString("payment"))))cashSales+=sale.optDouble("lineTotal",sale.optDouble("qty",0)*sale.optDouble("price",0));}
        metric("Gastos acumulados",money(expenseTotal));metric("Ingresos manuales",money(cashIn));metric("Retiros manuales",money(cashOut));metric("Efectivo estimado",money(cashSales+cashIn-cashOut-expenseTotal));
        Button addExpense=button("+ Registrar gasto",navy);addExpense.setOnClickListener(v->editExpense(-1));content.addView(addExpense);
        Button addIncome=button("+ Registrar ingreso de caja",earth);addIncome.setOnClickListener(v->editCashMovement("income"));content.addView(addIncome);
        Button addWithdrawal=button("− Registrar retiro de caja",Color.rgb(150,80,65));addWithdrawal.setOnClickListener(v->editCashMovement("withdrawal"));content.addView(addWithdrawal);
        content.addView(text("Historial de gastos",19,true,navy));
        if(expenses.length()==0)content.addView(text("Todavía no hay gastos registrados.",14,false,Color.GRAY));
        for(int i=expenses.length()-1;i>=0;i--){final int ix=i;JSONObject e=expenses.optJSONObject(i);if(e==null)continue;LinearLayout card=column();card.setBackgroundColor(Color.WHITE);card.addView(text(e.optString("name",e.optString("concept","Gasto")),17,true,navy));card.addView(text(money(e.optDouble("amount",0))+" · "+e.optString("date","")+" · "+e.optString("type","variable"),14,false,Color.DKGRAY));LinearLayout actions=new LinearLayout(this);Button edit=button("Editar",earth),del=button("Eliminar",Color.rgb(160,65,65));edit.setOnClickListener(v->editExpense(ix));del.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Eliminar gasto").setMessage("¿Quieres eliminar este gasto?").setNegativeButton("Cancelar",null).setPositiveButton("Eliminar",(d,w)->{expenses.remove(ix);saveAndSync("Gasto eliminado.");}).show());actions.addView(edit,new LinearLayout.LayoutParams(0,dp(48),1));actions.addView(del,new LinearLayout.LayoutParams(0,dp(48),1));card.addView(actions);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(8);content.addView(card,lp);}
        content.addView(text("Movimientos de caja",19,true,navy));if(cashMovements.length()==0)content.addView(text("Todavía no hay ingresos ni retiros manuales.",14,false,Color.GRAY));
        for(int i=cashMovements.length()-1;i>=0;i--){JSONObject m=cashMovements.optJSONObject(i);if(m==null)continue;String label="income".equals(m.optString("kind"))?"Ingreso":"Retiro";content.addView(text(label+" · "+m.optString("description","Movimiento")+" · "+money(m.optDouble("amount",0))+" · "+m.optString("date",""),14,false,Color.DKGRAY));}
    }
    private void editExpense(int index){boolean editing=index>=0;JSONObject old=editing?expenses.optJSONObject(index):null;LinearLayout form=column();EditText name=field(form,"Concepto del gasto",old==null?"":old.optString("name",old.optString("concept","")),InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);EditText amount=field(form,"Importe",old==null?"":String.valueOf(old.optDouble("amount",0)),InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);EditText date=field(form,"Fecha (AAAA-MM-DD)",old==null?today():old.optString("date",today()),InputType.TYPE_CLASS_DATETIME|InputType.TYPE_DATETIME_VARIATION_DATE);EditText type=field(form,"Tipo: fixed o variable",old==null?"variable":old.optString("type","variable"),InputType.TYPE_CLASS_TEXT);EditText frequency=field(form,"Frecuencia: once, monthly, weekly",old==null?"once":old.optString("frequency","once"),InputType.TYPE_CLASS_TEXT);
        new AlertDialog.Builder(this).setTitle(editing?"Editar gasto":"Registrar gasto").setView(form).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",(d,w)->{String n=name.getText().toString().trim(),dt=date.getText().toString().trim();double a=parse(amount.getText().toString());String ty=type.getText().toString().trim();if(n.isEmpty()||a<=0||!dt.matches("\\d{4}-\\d{2}-\\d{2}")){Toast.makeText(this,"Revisa concepto, importe y fecha.",Toast.LENGTH_LONG).show();return;}try{JSONObject item=old==null?new JSONObject():new JSONObject(old.toString());item.put("id",item.optString("id","native-expense-"+System.currentTimeMillis()));item.put("name",n);item.put("amount",a);item.put("date",dt);item.put("type",ty.isEmpty()?"variable":ty);item.put("frequency",frequency.getText().toString().trim().isEmpty()?"once":frequency.getText().toString().trim());if(editing)expenses.put(index,item);else expenses.put(item);saveAndSync(editing?"Gasto actualizado.":"Gasto registrado.");}catch(Exception ex){Toast.makeText(this,"No se pudo guardar el gasto.",Toast.LENGTH_LONG).show();}}).show();
    }
    private void editCashMovement(String kind){LinearLayout form=column();EditText description=field(form,"Descripción", "",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);EditText amount=field(form,"Importe", "",InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);EditText date=field(form,"Fecha (AAAA-MM-DD)",today(),InputType.TYPE_CLASS_DATETIME|InputType.TYPE_DATETIME_VARIATION_DATE);String title="income".equals(kind)?"Registrar ingreso":"Registrar retiro";new AlertDialog.Builder(this).setTitle(title).setView(form).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",(d,w)->{String desc=description.getText().toString().trim(),dt=date.getText().toString().trim();double a=parse(amount.getText().toString());if(desc.isEmpty()||a<=0||!dt.matches("\\d{4}-\\d{2}-\\d{2}")){Toast.makeText(this,"Revisa descripción, importe y fecha.",Toast.LENGTH_LONG).show();return;}try{JSONObject m=new JSONObject();m.put("id","native-cash-"+System.currentTimeMillis());m.put("kind",kind);m.put("description",desc);m.put("amount",a);m.put("date",dt);cashMovements.put(m);saveAndSync("Movimiento de caja registrado.");}catch(Exception ex){Toast.makeText(this,"No se pudo guardar el movimiento.",Toast.LENGTH_LONG).show();}}).show();
    }
    private void chooseProduct(){if(products.length()==0){Toast.makeText(this,"Primero registra productos en Inventario.",Toast.LENGTH_LONG).show();return;}java.util.ArrayList<JSONObject> available=new java.util.ArrayList<>();java.util.ArrayList<String> labels=new java.util.ArrayList<>();for(int i=0;i<products.length();i++){JSONObject p=products.optJSONObject(i);if(p!=null){available.add(p);labels.add(p.optString("name",p.optString("nombre","Producto"))+" · "+money(p.optDouble("price",0))+" · stock "+p.optDouble("stock",0));}}String[] options=labels.toArray(new String[0]);new AlertDialog.Builder(this).setTitle("Selecciona un producto").setItems(options,(d,which)->{JSONObject p=available.get(which);String id=productId(p,productsIndex(p));int old=cart.containsKey(id)?cart.get(id):0;if(old+1>p.optDouble("stock",0)){Toast.makeText(this,"Stock insuficiente para agregar este producto.",Toast.LENGTH_LONG).show();return;}cart.put(id,old+1);showScreen("Ventas");}).setNegativeButton("Cancelar",null).show();}
    private int productsIndex(JSONObject product){for(int i=0;i<products.length();i++)if(products.optJSONObject(i)==product)return i;return -1;}
    private void checkout(double total,double subtotal,double tax){
        if(cart.isEmpty())return;
        for(Map.Entry<String,Integer> e:cart.entrySet()){JSONObject p=findProduct(e.getKey());if(p==null||e.getValue()<=0||e.getValue()>p.optDouble("stock",0)){Toast.makeText(this,"Revisa el stock antes de cobrar.",Toast.LENGTH_LONG).show();return;}}
        new AlertDialog.Builder(this).setTitle("Forma de venta").setItems(new String[]{"Venta de contado","Venta fiada (a crédito)"},(d,which)->{if(which==0)checkoutCash(total,subtotal,tax);else chooseCreditCustomer(total,subtotal,tax);}).setNegativeButton("Cancelar",null).show();
    }
    private void checkoutCash(double total,double subtotal,double tax){EditText paid=new EditText(this);paid.setSingleLine(true);paid.setHint("Cantidad recibida");paid.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);new AlertDialog.Builder(this).setTitle("Cobrar "+money(total)).setMessage("Escribe cuánto pagó el cliente.").setView(paid).setNegativeButton("Cancelar",null).setPositiveButton("Confirmar venta",(dialog,which)->{double payment=parse(paid.getText().toString());if(payment<total){Toast.makeText(this,"El pago es menor que el total. La venta no se registró.",Toast.LENGTH_LONG).show();return;}registerSale(subtotal,tax,total,payment,"cash",null);}).show();}
    private void chooseCreditCustomer(double total,double subtotal,double tax){if(customers.length()==0){new AlertDialog.Builder(this).setTitle("No hay clientes").setMessage("Registra primero un cliente para poder vender fiado.").setPositiveButton("Registrar cliente",(d,w)->showScreen("Clientes")).setNegativeButton("Cancelar",null).show();return;}java.util.ArrayList<JSONObject> list=new java.util.ArrayList<>();java.util.ArrayList<String> labels=new java.util.ArrayList<>();for(int i=0;i<customers.length();i++){JSONObject c=customers.optJSONObject(i);if(c!=null){list.add(c);labels.add(c.optString("name","Cliente")+" · debe "+money(customerBalance(c.optString("id"))));}}new AlertDialog.Builder(this).setTitle("¿A qué cliente se le fía?").setItems(labels.toArray(new String[0]),(d,w)->new AlertDialog.Builder(this).setTitle("Confirmar venta fiada").setMessage("Se registrará una deuda de "+money(total)+" a nombre de "+list.get(w).optString("name")+". No se agregará dinero a caja.").setNegativeButton("Cancelar",null).setPositiveButton("Confirmar fiado",(dd,ww)->registerSale(subtotal,tax,total,0,"fiado",list.get(w).optString("id"))).show()).setNegativeButton("Cancelar",null).show();}
    private void registerSale(double subtotal,double tax,double total,double payment,String paymentType,String customerId){try{String saleId="N36-"+System.currentTimeMillis();String date=today();int index=0;for(Map.Entry<String,Integer> e:cart.entrySet()){JSONObject p=findProduct(e.getKey());if(p==null)throw new IllegalStateException("Producto no encontrado");int qty=e.getValue();double lineSubtotal=p.optDouble("price",0)*qty;double lineTax=cart.size()==index+1?tax:subtotal==0?0:tax*lineSubtotal/subtotal;double lineTotal="included".equals(taxMode())?lineSubtotal:lineSubtotal+lineTax;JSONObject sale=new JSONObject();sale.put("id",saleId+"-"+index);sale.put("saleId",saleId);sale.put("productId",p.optString("id",e.getKey()));sale.put("name",p.optString("name",p.optString("nombre","Producto")));sale.put("qty",qty);sale.put("price",p.optDouble("price",0));sale.put("cost",p.optDouble("cost",0));sale.put("date",date);sale.put("taxRate",taxRate());sale.put("taxMode",taxMode());sale.put("taxAmount",lineTax);sale.put("lineTotal",lineTotal);sale.put("saleSubtotal",subtotal);sale.put("saleTax",tax);sale.put("saleTotal",total);sale.put("source","native_pos");sale.put("payment",paymentType);if(customerId!=null)sale.put("customerId",customerId);sales.put(sale);p.put("stock",p.optDouble("stock",0)-qty);JSONObject move=new JSONObject();move.put("id",saleId+"-stock-"+index);move.put("date",date);move.put("productId",p.optString("id",e.getKey()));move.put("name",p.optString("name",p.optString("nombre","Producto")));move.put("typeLabel","Venta punto de venta nativo");move.put("qty",qty);move.put("reason",("fiado".equals(paymentType)?"Venta fiada ":"Venta ")+saleId);JSONArray moves=data.optJSONArray("stockMoves");if(moves==null){moves=new JSONArray();data.put("stockMoves",moves);}moves.put(move);index++;}
        if("fiado".equals(paymentType)){JSONObject charge=new JSONObject();charge.put("id","native-credit-"+System.currentTimeMillis());charge.put("customerId",customerId);charge.put("type","charge");charge.put("amount",total);charge.put("date",date);charge.put("description","Venta fiada · Folio "+saleId);creditMovements.put(charge);}
        data.put("products",products);data.put("sales",sales);data.put("customers",customers);data.put("creditMovements",creditMovements);if(!NativeDataStore.writeLegacyData(this,data))throw new IllegalStateException("No se pudieron guardar los datos");if(!MainActivity.applyNativeData(data.toString()))Toast.makeText(this,"Venta guardada en copia nativa; revisa sincronización.",Toast.LENGTH_LONG).show();else Toast.makeText(this,"fiado".equals(paymentType)?"Venta fiada registrada. No se recibió efectivo.":"Venta registrada. Cambio: "+money(payment-total),Toast.LENGTH_LONG).show();cart.clear();loadData();showScreen("Ventas");}catch(Exception ex){Toast.makeText(this,"No se pudo registrar la venta: "+ex.getMessage(),Toast.LENGTH_LONG).show();}}
    private double customerBalance(String id){double balance=0;for(int i=0;i<creditMovements.length();i++){JSONObject m=creditMovements.optJSONObject(i);if(m!=null&&id.equals(m.optString("customerId"))){double a=m.optDouble("amount",0);if("charge".equals(m.optString("type")))balance+=a;else if("payment".equals(m.optString("type")))balance-=a;}}return Math.max(0,balance);}
    private void showCustomers(){content.addView(text("Clientes y fiado",24,true,navy));content.addView(text("Administra clientes, registra deudas y recibe abonos sin contarlos como ventas.",14,false,Color.DKGRAY));double due=0;for(int i=0;i<customers.length();i++){JSONObject c=customers.optJSONObject(i);if(c!=null)due+=customerBalance(c.optString("id"));}metric("Saldo total pendiente",money(due));metric("Clientes registrados",String.valueOf(customers.length()));Button add=button("+ Registrar cliente",navy);add.setOnClickListener(v->editCustomer(-1));content.addView(add);Button debt=button("+ Agregar deuda manual",earth);debt.setOnClickListener(v->addManualDebt());content.addView(debt);Button payment=button("Registrar abono",earth);payment.setOnClickListener(v->recordCreditPayment());content.addView(payment);content.addView(text("Cartera de clientes",19,true,navy));if(customers.length()==0)content.addView(text("Todavía no hay clientes registrados.",14,false,Color.GRAY));for(int i=0;i<customers.length();i++){final int ix=i;JSONObject c=customers.optJSONObject(i);if(c==null)continue;String id=c.optString("id");LinearLayout card=column();card.setBackgroundColor(Color.WHITE);card.addView(text(c.optString("name","Cliente"),18,true,navy));card.addView(text(c.optString("phone","Sin teléfono"),14,false,Color.DKGRAY));card.addView(text("Saldo pendiente: "+money(customerBalance(id)),15,true,customerBalance(id)>0?Color.rgb(160,65,65):Color.rgb(50,130,80)));Button edit=button("Editar cliente",earth);edit.setOnClickListener(v->editCustomer(ix));card.addView(edit);Button history=button("Ver movimientos",navy);history.setOnClickListener(v->showCustomerHistory(id));card.addView(history);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(9);content.addView(card,lp);}}
    private void editCustomer(int index){boolean editing=index>=0;JSONObject old=editing?customers.optJSONObject(index):null;LinearLayout form=column();EditText name=field(form,"Nombre del cliente",old==null?"":old.optString("name",""),InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);EditText phone=field(form,"Teléfono (opcional)",old==null?"":old.optString("phone",""),InputType.TYPE_CLASS_PHONE);EditText initial=field(form,"Deuda inicial (opcional)","0",InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);new AlertDialog.Builder(this).setTitle(editing?"Editar cliente":"Registrar cliente").setView(form).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",(d,w)->{String n=name.getText().toString().trim();if(n.isEmpty()){Toast.makeText(this,"Escribe el nombre del cliente.",Toast.LENGTH_LONG).show();return;}try{JSONObject c=old==null?new JSONObject():new JSONObject(old.toString());String id=c.optString("id","native-customer-"+System.currentTimeMillis());c.put("id",id);c.put("name",n);c.put("phone",phone.getText().toString().trim());if(!editing){c.put("createdAt",today());customers.put(c);double debt=parse(initial.getText().toString());if(debt>0){JSONObject m=new JSONObject();m.put("id","native-credit-"+System.currentTimeMillis());m.put("customerId",id);m.put("type","charge");m.put("amount",debt);m.put("date",today());m.put("description","Saldo inicial del cliente");creditMovements.put(m);}}else customers.put(index,c);saveCustomerData(editing?"Cliente actualizado.":"Cliente registrado.");}catch(Exception e){Toast.makeText(this,"No se pudo guardar el cliente.",Toast.LENGTH_LONG).show();}}).show();}
    private void addManualDebt(){if(customers.length()==0){Toast.makeText(this,"Primero registra un cliente.",Toast.LENGTH_LONG).show();return;}chooseCustomerAmount(false);}
    private void recordCreditPayment(){if(customers.length()==0){Toast.makeText(this,"No hay clientes registrados.",Toast.LENGTH_LONG).show();return;}chooseCustomerAmount(true);}
    private void chooseCustomerAmount(boolean isPayment){java.util.ArrayList<JSONObject> list=new java.util.ArrayList<>();java.util.ArrayList<String> labels=new java.util.ArrayList<>();for(int i=0;i<customers.length();i++){JSONObject c=customers.optJSONObject(i);if(c!=null&&(!isPayment||customerBalance(c.optString("id"))>0)){list.add(c);labels.add(c.optString("name","Cliente")+" · debe "+money(customerBalance(c.optString("id"))));}}if(list.isEmpty()){Toast.makeText(this,"No hay saldos pendientes para abonar.",Toast.LENGTH_LONG).show();return;}new AlertDialog.Builder(this).setTitle(isPayment?"Selecciona cliente para abonar":"Selecciona cliente para agregar deuda").setItems(labels.toArray(new String[0]),(d,w)->creditAmountDialog(list.get(w),isPayment)).setNegativeButton("Cancelar",null).show();}
    private void creditAmountDialog(JSONObject customer,boolean isPayment){LinearLayout form=column();EditText amount=field(form,"Importe", "",InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);EditText desc=field(form,"Descripción (opcional)",isPayment?"Abono recibido":"Deuda agregada manualmente",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);new AlertDialog.Builder(this).setTitle(isPayment?"Registrar abono":"Agregar deuda").setMessage(customer.optString("name")).setView(form).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",(d,w)->{double a=parse(amount.getText().toString());String id=customer.optString("id");if(a<=0||(isPayment&&a>customerBalance(id))){Toast.makeText(this,isPayment?"El abono debe ser mayor que cero y no superar la deuda.":"Introduce un importe válido.",Toast.LENGTH_LONG).show();return;}try{JSONObject m=new JSONObject();m.put("id","native-credit-"+System.currentTimeMillis());m.put("customerId",id);m.put("type",isPayment?"payment":"charge");m.put("amount",a);m.put("date",today());m.put("description",desc.getText().toString().trim().isEmpty()?(isPayment?"Abono recibido":"Deuda agregada manualmente"):desc.getText().toString().trim());creditMovements.put(m);saveCustomerData(isPayment?"Abono registrado; no se creó una venta.":"Deuda agregada al cliente.");}catch(Exception ex){Toast.makeText(this,"No se pudo guardar el movimiento.",Toast.LENGTH_LONG).show();}}).show();}
    private void showCustomerHistory(String id){StringBuilder b=new StringBuilder();for(int i=creditMovements.length()-1;i>=0;i--){JSONObject m=creditMovements.optJSONObject(i);if(m!=null&&id.equals(m.optString("customerId")))b.append("payment".equals(m.optString("type"))?"Abono":"Deuda").append(" · ").append(money(m.optDouble("amount",0))).append(" · ").append(m.optString("date","")).append("\n").append(m.optString("description","")).append("\n\n");}if(b.length()==0)b.append("Sin movimientos.");new AlertDialog.Builder(this).setTitle("Historial del cliente").setMessage(b.toString()).setPositiveButton("Cerrar",null).show();}
    private void saveCustomerData(String message){try{data.put("customers",customers);data.put("creditMovements",creditMovements);data.put("sales",sales);data.put("products",products);if(!NativeDataStore.writeLegacyData(this,data)){Toast.makeText(this,"No se pudieron guardar los cambios.",Toast.LENGTH_LONG).show();return;}if(!MainActivity.applyNativeData(data.toString()))Toast.makeText(this,"Guardado en copia nativa; revisa la sincronización.",Toast.LENGTH_LONG).show();else Toast.makeText(this,message,Toast.LENGTH_SHORT).show();loadData();showScreen("Clientes");}catch(Exception e){Toast.makeText(this,"Error al guardar: "+e.getMessage(),Toast.LENGTH_LONG).show();}}
    private EditText field(LinearLayout box,String hint,String value,int type){EditText e=new EditText(this);e.setSingleLine(true);e.setHint(hint);e.setText(value);e.setInputType(type);box.addView(e);return e;}
    private void editProduct(int index){boolean editing=index>=0;JSONObject old=editing?products.optJSONObject(index):null;LinearLayout form=column();EditText name=field(form,"Nombre del producto",old==null?"":old.optString("name",old.optString("nombre","")),InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);EditText price=field(form,"Precio de venta",old==null?"":String.valueOf(old.optDouble("price",0)),InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);EditText stock=field(form,"Existencias",old==null?"0":String.valueOf(old.optDouble("stock",0)),InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);EditText min=field(form,"Stock mínimo",old==null?"0":String.valueOf(old.optDouble("minStock",0)),InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);new AlertDialog.Builder(this).setTitle(editing?"Editar producto":"Agregar producto").setView(form).setNegativeButton("Cancelar",(d,w)->{}).setPositiveButton("Guardar",(d,w)->{String n=name.getText().toString().trim();double pr=parse(price.getText().toString()),st=parse(stock.getText().toString()),mn=parse(min.getText().toString());if(n.isEmpty()||pr<0||st<0||mn<0){Toast.makeText(this,"Revisa el nombre y los valores; no pueden ser negativos.",Toast.LENGTH_LONG).show();return;}try{JSONObject p=old==null?new JSONObject():new JSONObject(old.toString());p.put("name",n);p.put("price",pr);p.put("stock",st);p.put("minStock",mn);if(editing)products.put(index,p);else products.put(p);data.put("products",products);if(!NativeDataStore.writeLegacyData(this,data)){Toast.makeText(this,"No se pudieron guardar los cambios.",Toast.LENGTH_LONG).show();return;}if(!MainActivity.applyNativeData(data.toString())){Toast.makeText(this,"Se guardó la copia nativa, pero no se pudo confirmar la sincronización con la pantalla principal. Abre la app principal y verifica los datos antes de seguir editando.",Toast.LENGTH_LONG).show();}else Toast.makeText(this,"Producto guardado y sincronizado.",Toast.LENGTH_SHORT).show();loadData();showScreen("Inventario");}catch(Exception e){Toast.makeText(this,"No se pudo guardar el producto.",Toast.LENGTH_LONG).show();}}).show();}
    private double parse(String s){try{return Double.parseDouble(s.trim().replace(',','.'));}catch(Exception e){return -1;}}
}
